export function createServiceWorker() {
  return `// Service Worker — Offline Shell & Asset Cache
const CACHE_NAME = 'quest-ky-shell-v1';
const SHELL_URLS = ['/', '/manifest.webmanifest'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(SHELL_URLS))
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))
      )
    )
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);

  if (url.pathname === '/' || url.pathname === '/manifest.webmanifest') {
    event.respondWith(
      caches.match(event.request).then((cachedResponse) => {
        const fetchPromise = fetch(event.request).then((networkResponse) => {
          if (networkResponse && networkResponse.status === 200) {
            const responseClone = networkResponse.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(event.request, responseClone));
          }
          return networkResponse;
        }).catch(() => cachedResponse);
        return cachedResponse || fetchPromise;
      })
    );
  }
});`;
}

const CLIENT_BUNDLE = "/* --- CONSTANTS & CONFIG --- */\n\n// src/data/constants.js — Centralized Project Constants\r\n// Single source of truth for dimensions, palette, subjects, and gameplay rules.\r\n\r\nconst VIEWPORT = {\r\n  LOGICAL_WIDTH: 320,\r\n  LOGICAL_HEIGHT: 240,\r\n  TILE_SIZE: 16,\r\n  MIN_TOUCH_TARGET: 48, // Minimum 48x48px for WCAG 2.5.5\r\n};\r\n\r\nconst PALETTE = {\r\n  // Canvas & UI Surfaces\r\n  BG_DARK: '#0F172A',         // Slate 900\r\n  SURFACE: '#1E293B',         // Slate 800\r\n  SURFACE_ELEVATED: '#334155',// Slate 700\r\n  SURFACE_ACCENT: '#475569',  // Slate 600\r\n  BORDER_SUBTLE: '#334155',   // Slate 700\r\n  BORDER_FOCUS: '#38BDF8',    // Sky 400\r\n  PARCHMENT: '#FEF3C7',       // Amber 100\r\n  PARCHMENT_BORDER: '#D97706',// Amber 600\r\n\r\n  // Text Tokens\r\n  TEXT_PRIMARY: '#F8FAFC',    // Slate 50\r\n  TEXT_SECONDARY: '#94A3B8',  // Slate 400\r\n  TEXT_DARK: '#0F172A',       // Slate 900\r\n\r\n  // Feedback Tokens\r\n  SUCCESS: '#10B981',         // Emerald 500\r\n  WARNING: '#F59E0B',         // Amber 500\r\n  ERROR: '#EF4444',           // Red 500\r\n  GOLD: '#FBBF24',            // Amber 400\r\n\r\n  // KAAC Governor's Cup Subjects\r\n  MATH: '#2563EB',            // Blue 600 (Cipher Caverns)\r\n  SCIENCE: '#059669',         // Emerald 600 (Verdant Wilds)\r\n  SOCIAL_STUDIES: '#D97706',  // Amber 600 (Kingdoms of Time)\r\n  LANGUAGE_ARTS: '#7C3AED',   // Violet 600 (Whispering Archives)\r\n  ARTS_HUMANITIES: '#DB2777', // Pink 600 (Gallery of Wonders)\r\n};\r\n\r\nconst SUBJECTS = {\r\n  MATH: {\r\n    id: 'math',\r\n    name: 'Mathematics',\r\n    color: PALETTE.MATH,\r\n    realm: 'Cipher Caverns',\r\n    boss: 'Number Golem',\r\n  },\r\n  SCIENCE: {\r\n    id: 'science',\r\n    name: 'Science',\r\n    color: PALETTE.SCIENCE,\r\n    realm: 'Verdant Wilds',\r\n    boss: 'Overgrown Guardian',\r\n  },\r\n  SOCIAL_STUDIES: {\r\n    id: 'social_studies',\r\n    name: 'Social Studies',\r\n    color: PALETTE.SOCIAL_STUDIES,\r\n    realm: 'Kingdoms of Time',\r\n    boss: 'Chrono Warden',\r\n  },\r\n  LANGUAGE_ARTS: {\r\n    id: 'language_arts',\r\n    name: 'Language Arts',\r\n    color: PALETTE.LANGUAGE_ARTS,\r\n    realm: 'Whispering Archives',\r\n    boss: 'Wordweaver',\r\n  },\r\n  ARTS_HUMANITIES: {\r\n    id: 'arts_humanities',\r\n    name: 'Arts and Humanities',\r\n    color: PALETTE.ARTS_HUMANITIES,\r\n    realm: 'Gallery of Wonders',\r\n    boss: 'Living Masterpiece',\r\n  },\r\n};\r\n\r\nconst SPACED_REPETITION = {\r\n  INTERVALS_DAYS: [1, 3, 7, 14, 30],\r\n  VERIFICATION_MIN_COUNT: 3, // Requires 3 distinct questions to verify mastery\r\n};\r\n\r\nconst TARGET_GRADE_BAND = '6-8'; // Middle Grades focus\n\n/* --- GAME DATA & GENERATORS --- */\n\n// src/data/game-data.js — Initial Game Data & Pseudonymous Generators\r\n// Child privacy: Zero PII. Adventurer handles are procedurally generated.\r\n\r\n\r\nconst HANDLE_PREFIXES = [\r\n  'Bluegrass', 'Cumberland', 'Berea', 'Derby', 'Cardinal',\r\n  'RedRiver', 'Limestone', 'Mammoth', 'Goldenrod', 'Paducah'\r\n];\r\n\r\nconst HANDLE_ROLES = [\r\n  'Wizard', 'Scholar', 'Ranger', 'Pioneer', 'Alchemist',\r\n  'Chronologer', 'Sage', 'Navigator', 'Wordweaver', 'Guardian'\r\n];\r\n\r\n/**\r\n * Procedurally generates a child-safe pseudonymous adventurer handle.\r\n * Follows COPPA compliance: Zero PII, no real names or identifiers.\r\n * @param {() => number} [rng=Math.random]\r\n * @returns {string} e.g. \"BluegrassWizard42\"\r\n */\r\nfunction generateAdventurerHandle(rng = Math.random) {\r\n  const prefix = HANDLE_PREFIXES[Math.floor(rng() * HANDLE_PREFIXES.length)];\r\n  const role = HANDLE_ROLES[Math.floor(rng() * HANDLE_ROLES.length)];\r\n  const num = Math.floor(rng() * 90) + 10;\r\n  return `${prefix}${role}${num}`;\r\n}\r\n\r\n/**\r\n * Initial Starter Quests aligned with Governor's Cup subject realms.\r\n */\r\nconst STARTER_QUESTS = [\r\n  {\r\n    id: 'quest_math_01',\r\n    subjectId: 'math',\r\n    title: \"The Cipher's Enigma\",\r\n    realm: SUBJECTS.MATH.realm,\r\n    color: SUBJECTS.MATH.color,\r\n    description: 'Investigate strange numerical runes in the Cipher Caverns.',\r\n    status: 'active',\r\n    progress: '0 / 3 Runes Decoded',\r\n    rewardXp: 150,\r\n    rewardGold: 25,\r\n  },\r\n  {\r\n    id: 'quest_science_01',\r\n    subjectId: 'science',\r\n    title: 'Flora of the Verdant Wilds',\r\n    realm: SUBJECTS.SCIENCE.realm,\r\n    color: SUBJECTS.SCIENCE.color,\r\n    description: 'Catalog photosynthetic anomalies along the wild moss river.',\r\n    status: 'available',\r\n    progress: 'Not Started',\r\n    rewardXp: 120,\r\n    rewardGold: 20,\r\n  },\r\n  {\r\n    id: 'quest_social_01',\r\n    subjectId: 'social_studies',\r\n    title: 'Echoes of the Commonwealth',\r\n    realm: SUBJECTS.SOCIAL_STUDIES.realm,\r\n    color: SUBJECTS.SOCIAL_STUDIES.color,\r\n    description: 'Uncover ancient historical decrees inside the Chrono Archives.',\r\n    status: 'available',\r\n    progress: 'Not Started',\r\n    rewardXp: 140,\r\n    rewardGold: 30,\r\n  },\r\n  {\r\n    id: 'quest_lang_01',\r\n    subjectId: 'language_arts',\r\n    title: 'The Whispering Tomes',\r\n    realm: SUBJECTS.LANGUAGE_ARTS.realm,\r\n    color: SUBJECTS.LANGUAGE_ARTS.color,\r\n    description: 'Restore missing allegorical stanzas to the Great Library.',\r\n    status: 'available',\r\n    progress: 'Not Started',\r\n    rewardXp: 130,\r\n    rewardGold: 20,\r\n  },\r\n  {\r\n    id: 'quest_arts_01',\r\n    subjectId: 'arts_humanities',\r\n    title: 'Harmony of the Spheres',\r\n    realm: SUBJECTS.ARTS_HUMANITIES.realm,\r\n    color: SUBJECTS.ARTS_HUMANITIES.color,\r\n    description: 'Tune the resonant crystal bells in the Gallery of Wonders.',\r\n    status: 'available',\r\n    progress: 'Not Started',\r\n    rewardXp: 160,\r\n    rewardGold: 35,\r\n  },\r\n];\r\n\r\n/**\r\n * Initial Starter Inventory items with procedural icon types and stats.\r\n */\r\nconst STARTER_INVENTORY = [\r\n  {\r\n    id: 'item_compass',\r\n    name: \"Scholar's Compass\",\r\n    type: 'gear',\r\n    slot: 'relic',\r\n    subject: 'General',\r\n    color: PALETTE.GOLD,\r\n    icon: 'compass',\r\n    description: 'Points toward undiscovered knowledge nodes across Kentucky.',\r\n    equipped: true,\r\n  },\r\n  {\r\n    id: 'item_quill',\r\n    name: 'Novice Quill',\r\n    type: 'gear',\r\n    slot: 'weapon',\r\n    subject: 'Language Arts',\r\n    color: PALETTE.LANGUAGE_ARTS,\r\n    icon: 'quill',\r\n    description: 'Inscribes answers swiftly during speed buzzer rounds.',\r\n    equipped: true,\r\n  },\r\n  {\r\n    id: 'item_scroll',\r\n    name: 'Parchment Scroll',\r\n    type: 'consumable',\r\n    slot: null,\r\n    subject: 'Social Studies',\r\n    color: PALETTE.PARCHMENT_BORDER,\r\n    icon: 'scroll',\r\n    description: 'Reveals one historical hint during an encounter.',\r\n    equipped: false,\r\n    quantity: 2,\r\n  },\r\n  {\r\n    id: 'item_flask',\r\n    name: 'Elixir of Focus',\r\n    type: 'consumable',\r\n    slot: null,\r\n    subject: 'Science',\r\n    color: PALETTE.SCIENCE,\r\n    icon: 'flask',\r\n    description: 'Restores 25 Energy points when facing challenging questions.',\r\n    equipped: false,\r\n    quantity: 3,\r\n  },\r\n  {\r\n    id: 'item_sigil',\r\n    name: \"Governor's Sigil\",\r\n    type: 'artifact',\r\n    slot: null,\r\n    subject: 'General',\r\n    color: PALETTE.BORDER_FOCUS,\r\n    icon: 'sigil',\r\n    description: 'Mark of an official contender for the Governor\\'s Cup.',\r\n    equipped: false,\r\n    quantity: 1,\r\n  },\r\n];\r\n\r\n/**\r\n * Creates a pristine default player profile.\r\n * Stored locally in localStorage for 100% guest-first playability.\r\n * @returns {object}\r\n */\r\nfunction createDefaultPlayerProfile() {\r\n  return {\r\n    handle: generateAdventurerHandle(),\r\n    gradeBand: '6-8',\r\n    level: 1,\r\n    hp: 100,\r\n    maxHp: 100,\r\n    xp: 0,\r\n    maxXp: 100,\r\n    gold: 50,\r\n    activeRealm: 'Cipher Caverns',\r\n    inventory: STARTER_INVENTORY.map(item => ({ ...item })),\r\n    quests: STARTER_QUESTS.map(q => ({ ...q })),\r\n    settings: {\r\n      audioMuted: false,\r\n      reducedMotion: false,\r\n      highContrast: false,\r\n    },\r\n  };\r\n}\n\n/* --- PROCEDURAL SPRITES & ICONS --- */\n\n// src/client/sprites.js — Procedural Pixel Sprites & Vector Icons\r\n// Zero raster assets: All graphics are encoded in pixel matrices or vector formulas.\r\n\r\n\r\n/**\r\n * 8x8 Procedural Hero Sprites by Direction.\r\n * Palette indices:\r\n * 0 = transparent\r\n * 1 = skin (#FEF3C7)\r\n * 2 = cloak / tunic (#2563EB)\r\n * 3 = boots / belt / eyes (#0F172A)\r\n * 4 = gold trim (#FBBF24)\r\n * 5 = highlight / hair (#D97706)\r\n */\r\nconst HERO_SPRITES = {\r\n  down: {\r\n    palette: ['transparent', PALETTE.PARCHMENT, PALETTE.MATH, PALETTE.BG_DARK, PALETTE.GOLD, PALETTE.SOCIAL_STUDIES],\r\n    matrix: [\r\n      '05555550',\r\n      '55111155',\r\n      '51311315',\r\n      '01111110',\r\n      '02244220',\r\n      '22244222',\r\n      '02333320',\r\n      '03000030',\r\n    ],\r\n  },\r\n  up: {\r\n    palette: ['transparent', PALETTE.PARCHMENT, PALETTE.MATH, PALETTE.BG_DARK, PALETTE.GOLD, PALETTE.SOCIAL_STUDIES],\r\n    matrix: [\r\n      '05555550',\r\n      '55555555',\r\n      '55555555',\r\n      '01111110',\r\n      '02244220',\r\n      '22244222',\r\n      '02333320',\r\n      '03000030',\r\n    ],\r\n  },\r\n  left: {\r\n    palette: ['transparent', PALETTE.PARCHMENT, PALETTE.MATH, PALETTE.BG_DARK, PALETTE.GOLD, PALETTE.SOCIAL_STUDIES],\r\n    matrix: [\r\n      '05555500',\r\n      '55111500',\r\n      '51311500',\r\n      '01111000',\r\n      '02242200',\r\n      '02242220',\r\n      '02333000',\r\n      '00303000',\r\n    ],\r\n  },\r\n  right: {\r\n    palette: ['transparent', PALETTE.PARCHMENT, PALETTE.MATH, PALETTE.BG_DARK, PALETTE.GOLD, PALETTE.SOCIAL_STUDIES],\r\n    matrix: [\r\n      '00555550',\r\n      '00511155',\r\n      '00511315',\r\n      '00011110',\r\n      '00224220',\r\n      '02224220',\r\n      '00033320',\r\n      '00030300',\r\n    ],\r\n  },\r\n};\r\n\r\n/**\r\n * Draws a procedural pixel matrix sprite onto a canvas 2D context.\r\n * @param {CanvasRenderingContext2D} ctx\r\n * @param {object} sprite\r\n * @param {number} destX\r\n * @param {number} destY\r\n * @param {number} [pixelScale=2]\r\n */\r\nfunction renderPixelSprite(ctx, sprite, destX, destY, pixelScale = 2) {\r\n  if (!ctx || !sprite || !sprite.matrix) return;\r\n  for (let row = 0; row < sprite.matrix.length; row++) {\r\n    const line = sprite.matrix[row];\r\n    for (let col = 0; col < line.length; col++) {\r\n      const colorIndex = parseInt(line[col], 10);\r\n      if (colorIndex > 0 && sprite.palette[colorIndex]) {\r\n        ctx.fillStyle = sprite.palette[colorIndex];\r\n        ctx.fillRect(\r\n          Math.floor(destX + col * pixelScale),\r\n          Math.floor(destY + row * pixelScale),\r\n          pixelScale,\r\n          pixelScale\r\n        );\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n/**\r\n * Generates an offscreen Canvas texture atlas containing 16x16 procedural terrain tiles.\r\n * Caches grass, paths, water, trees, and subject stone shrines.\r\n * @returns {HTMLCanvasElement|null}\r\n */\r\nfunction createTileAtlas() {\r\n  if (typeof document === 'undefined') return null;\r\n\r\n  const atlas = document.createElement('canvas');\r\n  atlas.width = 128;\r\n  atlas.height = 128;\r\n  const ctx = atlas.getContext('2d');\r\n  if (!ctx) return null;\r\n\r\n  // 1. Grass Tile (Index 0: 0, 0)\r\n  ctx.fillStyle = '#065F46'; // Dark Emerald base\r\n  ctx.fillRect(0, 0, 16, 16);\r\n  ctx.fillStyle = '#059669'; // Emerald highlights\r\n  ctx.fillRect(2, 2, 2, 4);\r\n  ctx.fillRect(10, 3, 2, 5);\r\n  ctx.fillRect(6, 9, 2, 4);\r\n  ctx.fillRect(12, 11, 2, 3);\r\n  ctx.fillStyle = '#10B981'; // Bright tip\r\n  ctx.fillRect(2, 2, 2, 1);\r\n  ctx.fillRect(10, 3, 2, 1);\r\n  ctx.fillRect(6, 9, 2, 1);\r\n\r\n  // 2. Cobblestone Path Tile (Index 1: 16, 0)\r\n  ctx.fillStyle = '#334155'; // Slate 700 mortar\r\n  ctx.fillRect(16, 0, 16, 16);\r\n  ctx.fillStyle = '#475569'; // Slate 600 stone\r\n  ctx.fillRect(17, 1, 6, 6);\r\n  ctx.fillRect(25, 2, 6, 5);\r\n  ctx.fillRect(18, 9, 6, 6);\r\n  ctx.fillRect(26, 8, 5, 7);\r\n  ctx.fillStyle = '#64748B'; // Slate 500 edge highlight\r\n  ctx.fillRect(17, 1, 6, 1);\r\n  ctx.fillRect(25, 2, 6, 1);\r\n  ctx.fillRect(18, 9, 6, 1);\r\n\r\n  // 3. Water Tile (Index 2: 32, 0)\r\n  ctx.fillStyle = '#1E3A8A'; // Blue 900 base\r\n  ctx.fillRect(32, 0, 16, 16);\r\n  ctx.fillStyle = '#2563EB'; // Blue 600 wave\r\n  ctx.fillRect(34, 4, 8, 2);\r\n  ctx.fillRect(38, 10, 8, 2);\r\n  ctx.fillStyle = '#38BDF8'; // Sky 400 sparkle\r\n  ctx.fillRect(36, 4, 2, 1);\r\n  ctx.fillRect(42, 10, 2, 1);\r\n\r\n  // 4. Stone Wall / Dungeon Brick (Index 3: 48, 0)\r\n  ctx.fillStyle = '#0F172A'; // Slate 900 mortar\r\n  ctx.fillRect(48, 0, 16, 16);\r\n  ctx.fillStyle = '#1E293B'; // Slate 800 brick\r\n  ctx.fillRect(49, 1, 14, 6);\r\n  ctx.fillRect(49, 9, 14, 6);\r\n  ctx.fillStyle = '#334155'; // Slate 700 top highlight\r\n  ctx.fillRect(49, 1, 14, 1);\r\n  ctx.fillRect(49, 9, 14, 1);\r\n\r\n  // 5. Tree Foliage (Index 4: 64, 0)\r\n  ctx.fillStyle = '#064E3B'; // Deep green shadow\r\n  ctx.fillRect(64, 0, 16, 16);\r\n  ctx.fillStyle = '#059669'; // Emerald canopy\r\n  ctx.fillRect(66, 2, 12, 12);\r\n  ctx.fillStyle = '#10B981'; // Sunlight tip\r\n  ctx.fillRect(68, 4, 4, 4);\r\n\r\n  return atlas;\r\n}\r\n\r\n/**\r\n * Returns procedural inline SVG strings for UI icons without raster assets.\r\n * @param {string} iconName\r\n * @param {string} [color=PALETTE.TEXT_PRIMARY]\r\n * @param {number} [size=20]\r\n * @returns {string}\r\n */\r\nfunction getSvgIcon(iconName, color = PALETTE.TEXT_PRIMARY, size = 20) {\r\n  const common = `width=\"${size}\" height=\"${size}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"`;\r\n\r\n  switch (iconName) {\r\n    case 'compass':\r\n      return `<svg ${common}><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><polygon points=\"16.24 7.76 14.12 14.12 7.76 16.24 9.88 9.88 16.24 7.76\" fill=\"${color}\" fill-opacity=\"0.3\"></polygon></svg>`;\r\n    case 'quill':\r\n      return `<svg ${common}><path d=\"M12 19l7-7 3 3-7 7-3-3z\"></path><path d=\"M18 13l-1.5-7.5L2 2l3.5 14.5L13 18z\"></path><path d=\"M2 2l7.586 7.586\"></path><circle cx=\"11\" cy=\"11\" r=\"2\"></circle></svg>`;\r\n    case 'scroll':\r\n      return `<svg ${common}><path d=\"M19 17h2a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h2\"></path><path d=\"M15 21v-4a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v4a2 2 0 0 0 2 2h9a2 2 0 0 0 2-2z\"></path></svg>`;\r\n    case 'flask':\r\n      return `<svg ${common}><path d=\"M9 3h6\"></path><path d=\"M10 3v5l-4 7a2 2 0 0 0 1.7 3h8.6a2 2 0 0 0 1.7-3l-4-7V3\"></path><path d=\"M8 14h8\"></path></svg>`;\r\n    case 'sigil':\r\n      return `<svg ${common}><path d=\"M12 2l8 4.5v6c0 5-3.5 9.5-8 11-4.5-1.5-8-6-8-11v-6L12 2z\"></path><circle cx=\"12\" cy=\"11\" r=\"3\" fill=\"${color}\" fill-opacity=\"0.4\"></circle></svg>`;\r\n    case 'map':\r\n      return `<svg ${common}><polygon points=\"1 6 1 22 8 18 16 22 23 18 23 2 16 6 8 2 1 6\"></polygon><line x1=\"8\" y1=\"2\" x2=\"8\" y2=\"18\"></line><line x1=\"16\" y1=\"6\" x2=\"16\" y2=\"22\"></line></svg>`;\r\n    case 'quests':\r\n      return `<svg ${common}><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"></line><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"></line><polyline points=\"10 9 9 9 8 9\"></polyline></svg>`;\r\n    case 'inventory':\r\n      return `<svg ${common}><path d=\"M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z\"></path><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><path d=\"M16 10a4 4 0 0 1-8 0\"></path></svg>`;\r\n    case 'settings':\r\n      return `<svg ${common}><circle cx=\"12\" cy=\"12\" r=\"3\"></circle><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z\"></path></svg>`;\r\n    case 'audio-on':\r\n      return `<svg ${common}><polygon points=\"11 5 6 9 2 9 2 15 6 15 11 19 11 5\"></polygon><path d=\"M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07\"></path></svg>`;\r\n    case 'audio-off':\r\n      return `<svg ${common}><polygon points=\"11 5 6 9 2 9 2 15 6 15 11 19 11 5\"></polygon><line x1=\"23\" y1=\"9\" x2=\"17\" y2=\"15\"></line><line x1=\"17\" y1=\"9\" x2=\"23\" y2=\"15\"></line></svg>`;\r\n    case 'close':\r\n      return `<svg ${common}><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>`;\r\n    default:\r\n      return `<svg ${common}><circle cx=\"12\" cy=\"12\" r=\"10\"></circle></svg>`;\r\n  }\r\n}\n\n/* --- PROCEDURAL AUDIO SYNTHESIZER --- */\n\n// src/client/audio.js — Procedural Web Audio FX Synthesizer\r\n// Pure algorithmic sound synthesis with zero external audio assets.\r\n\r\nclass SoundEngine {\r\n  constructor() {\r\n    this.ctx = null;\r\n    this.muted = false;\r\n    this.initialized = false;\r\n  }\r\n\r\n  /**\r\n   * Initializes or resumes the AudioContext on first user gesture.\r\n   */\r\n  init() {\r\n    if (this.ctx) {\r\n      if (this.ctx.state === 'suspended') {\r\n        this.ctx.resume().catch(() => {});\r\n      }\r\n      return;\r\n    }\r\n\r\n    const AudioContextClass = globalThis.AudioContext || globalThis.webkitAudioContext;\r\n    if (AudioContextClass) {\r\n      try {\r\n        this.ctx = new AudioContextClass();\r\n        this.initialized = true;\r\n      } catch {\r\n        // Audio unavailable or blocked\r\n      }\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Toggles sound on or off.\r\n   * @param {boolean} [force]\r\n   * @returns {boolean} current muted state\r\n   */\r\n  toggleMute(force) {\r\n    this.muted = typeof force === 'boolean' ? force : !this.muted;\r\n    return this.muted;\r\n  }\r\n\r\n  isMuted() {\r\n    return this.muted;\r\n  }\r\n\r\n  /**\r\n   * Synthesizes an 8-bit style UI click.\r\n   */\r\n  playClick() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const now = this.ctx.currentTime;\r\n      const osc = this.ctx.createOscillator();\r\n      const gain = this.ctx.createGain();\r\n\r\n      osc.type = 'triangle';\r\n      osc.frequency.setValueAtTime(800, now);\r\n      osc.frequency.exponentialRampToValueAtTime(300, now + 0.04);\r\n\r\n      gain.gain.setValueAtTime(0.15, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.04);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(this.ctx.destination);\r\n\r\n      osc.start(now);\r\n      osc.stop(now + 0.04);\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes a friendly 3-note arpeggio chime (C5 - E5 - G5).\r\n   */\r\n  playChime() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const notes = [523.25, 659.25, 783.99]; // C5, E5, G5\r\n      const now = this.ctx.currentTime;\r\n\r\n      notes.forEach((freq, index) => {\r\n        const noteStart = now + index * 0.06;\r\n        const osc = this.ctx.createOscillator();\r\n        const gain = this.ctx.createGain();\r\n\r\n        osc.type = 'sine';\r\n        osc.frequency.setValueAtTime(freq, noteStart);\r\n\r\n        gain.gain.setValueAtTime(0.18, noteStart);\r\n        gain.gain.exponentialRampToValueAtTime(0.001, noteStart + 0.14);\r\n\r\n        osc.connect(gain);\r\n        gain.connect(this.ctx.destination);\r\n\r\n        osc.start(noteStart);\r\n        osc.stop(noteStart + 0.14);\r\n      });\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes a subtle, quiet movement tick.\r\n   */\r\n  playWalk() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const now = this.ctx.currentTime;\r\n      const osc = this.ctx.createOscillator();\r\n      const gain = this.ctx.createGain();\r\n\r\n      osc.type = 'triangle';\r\n      osc.frequency.setValueAtTime(140, now);\r\n      osc.frequency.exponentialRampToValueAtTime(60, now + 0.03);\r\n\r\n      gain.gain.setValueAtTime(0.06, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(this.ctx.destination);\r\n\r\n      osc.start(now);\r\n      osc.stop(now + 0.03);\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes a high modal opening cue.\r\n   */\r\n  playAlert() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const now = this.ctx.currentTime;\r\n      const osc = this.ctx.createOscillator();\r\n      const gain = this.ctx.createGain();\r\n\r\n      osc.type = 'sine';\r\n      osc.frequency.setValueAtTime(440, now);\r\n      osc.frequency.exponentialRampToValueAtTime(880, now + 0.08);\r\n\r\n      gain.gain.setValueAtTime(0.12, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(this.ctx.destination);\r\n\r\n      osc.start(now);\r\n      osc.stop(now + 0.08);\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n}\r\n\r\nconst soundEngine = new SoundEngine();\n\n/* --- DUAL KEYBOARD & TOUCH INPUT --- */\n\n// src/client/input.js — Dual Keyboard & Touch Input Abstraction\r\n// Handles mobile touch virtual D-Pad and keyboard navigation seamlessly.\r\n\r\nclass InputManager {\r\n  constructor() {\r\n    this.keysDown = new Set();\r\n    this.touchDown = new Set();\r\n    this.justPressed = new Set();\r\n    this.previousFrame = new Set();\r\n\r\n    // Map keyboard codes to logical game actions\r\n    this.keyMap = {\r\n      ArrowUp: 'up',\r\n      KeyW: 'up',\r\n      KeyK: 'up',\r\n      ArrowDown: 'down',\r\n      KeyS: 'down',\r\n      KeyJ: 'down',\r\n      ArrowLeft: 'left',\r\n      KeyA: 'left',\r\n      KeyH: 'left',\r\n      ArrowRight: 'right',\r\n      KeyD: 'right',\r\n      KeyL: 'right',\r\n      Space: 'action',\r\n      Enter: 'action',\r\n      KeyZ: 'action',\r\n      Escape: 'menu',\r\n      KeyM: 'menu',\r\n      KeyX: 'menu',\r\n    };\r\n\r\n    this.onKeyDown = this.onKeyDown.bind(this);\r\n    this.onKeyUp = this.onKeyUp.bind(this);\r\n  }\r\n\r\n  /**\r\n   * Initializes browser keyboard listeners if running in a DOM environment.\r\n   */\r\n  initKeyboard(target = globalThis.window) {\r\n    if (!target || typeof target.addEventListener !== 'function') return;\r\n    target.addEventListener('keydown', this.onKeyDown);\r\n    target.addEventListener('keyup', this.onKeyUp);\r\n  }\r\n\r\n  /**\r\n   * Cleans up browser listeners.\r\n   */\r\n  destroy(target = globalThis.window) {\r\n    if (!target || typeof target.removeEventListener !== 'function') return;\r\n    target.removeEventListener('keydown', this.onKeyDown);\r\n    target.removeEventListener('keyup', this.onKeyUp);\r\n  }\r\n\r\n  onKeyDown(event) {\r\n    const action = this.keyMap[event.code];\r\n    if (action) {\r\n      // Prevent browser scroll on arrow keys / spacebar during gameplay\r\n      if (['up', 'down', 'left', 'right', 'action'].includes(action)) {\r\n        if (typeof document !== 'undefined' && (event.target === document.body || (event.target && event.target.tagName === 'CANVAS'))) {\r\n          if (typeof event.preventDefault === 'function') {\r\n            event.preventDefault();\r\n          }\r\n        }\r\n      }\r\n      if (!this.keysDown.has(action)) {\r\n        this.justPressed.add(action);\r\n      }\r\n      this.keysDown.add(action);\r\n    }\r\n  }\r\n\r\n  onKeyUp(event) {\r\n    const action = this.keyMap[event.code];\r\n    if (action) {\r\n      this.keysDown.delete(action);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Sets touch action state programmatically (e.g. from virtual D-Pad or on-screen buttons).\r\n   * @param {string} action - 'up' | 'down' | 'left' | 'right' | 'action' | 'menu'\r\n   * @param {boolean} isPressed\r\n   */\r\n  setTouchAction(action, isPressed) {\r\n    if (isPressed) {\r\n      if (!this.touchDown.has(action)) {\r\n        this.justPressed.add(action);\r\n      }\r\n      this.touchDown.add(action);\r\n    } else {\r\n      this.touchDown.delete(action);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Checks if an action is currently held down via keyboard or touch.\r\n   * @param {string} action\r\n   * @returns {boolean}\r\n   */\r\n  isDown(action) {\r\n    return this.keysDown.has(action) || this.touchDown.has(action);\r\n  }\r\n\r\n  /**\r\n   * Checks if an action was newly triggered this frame.\r\n   * @param {string} action\r\n   * @returns {boolean}\r\n   */\r\n  isJustPressed(action) {\r\n    return this.justPressed.has(action);\r\n  }\r\n\r\n  /**\r\n   * Advance frame buffer — clears single-frame trigger events.\r\n   * Call once per animation frame tick.\r\n   */\r\n  update() {\r\n    this.justPressed.clear();\r\n  }\r\n\r\n  /**\r\n   * Binds virtual D-Pad touch/pointer events to HTML elements.\r\n   * Ensures touch-action: none and minimum 48px touch target support.\r\n   */\r\n  bindVirtualControls(elements) {\r\n    if (!elements) return;\r\n\r\n    const setupButton = (el, action) => {\r\n      if (!el) return;\r\n\r\n      const handlePress = (e) => {\r\n        if (e.cancelable) e.preventDefault();\r\n        this.setTouchAction(action, true);\r\n        el.setAttribute('data-active', 'true');\r\n      };\r\n\r\n      const handleRelease = (e) => {\r\n        if (e.cancelable) e.preventDefault();\r\n        this.setTouchAction(action, false);\r\n        el.removeAttribute('data-active');\r\n      };\r\n\r\n      el.addEventListener('pointerdown', handlePress);\r\n      el.addEventListener('pointerup', handleRelease);\r\n      el.addEventListener('pointercancel', handleRelease);\r\n      el.addEventListener('pointerleave', handleRelease);\r\n    };\r\n\r\n    if (elements.up) setupButton(elements.up, 'up');\r\n    if (elements.down) setupButton(elements.down, 'down');\r\n    if (elements.left) setupButton(elements.left, 'left');\r\n    if (elements.right) setupButton(elements.right, 'right');\r\n    if (elements.action) setupButton(elements.action, 'action');\r\n    if (elements.menu) setupButton(elements.menu, 'menu');\r\n  }\r\n}\n\n/* --- CANVAS 2D RENDERER --- */\n\n// src/client/renderer.js — 2D Canvas Procedural Game Engine\r\n// Renders 320x240 retro world with crisp pixel scaling and offscreen tile atlas.\r\n\r\n\r\nclass GameRenderer {\r\n  constructor(canvasElement) {\r\n    this.canvas = canvasElement;\r\n    this.ctx = canvasElement ? canvasElement.getContext('2d') : null;\r\n    this.atlas = null;\r\n\r\n    // Viewport dimensions\r\n    this.width = VIEWPORT.LOGICAL_WIDTH;\r\n    this.height = VIEWPORT.LOGICAL_HEIGHT;\r\n    this.tileSize = VIEWPORT.TILE_SIZE;\r\n\r\n    // World map grid: 20 cols x 16 rows (320px x 256px world)\r\n    this.cols = 20;\r\n    this.rows = 16;\r\n    this.worldWidth = this.cols * this.tileSize;\r\n    this.worldHeight = this.rows * this.tileSize;\r\n\r\n    // Camera\r\n    this.camera = { x: 0, y: 0 };\r\n\r\n    // Player state\r\n    this.player = {\r\n      x: 152, // Center of world\r\n      y: 120,\r\n      direction: 'down',\r\n      speed: 80, // pixels per second\r\n      width: 16,\r\n      height: 16,\r\n      moving: false,\r\n    };\r\n\r\n    // Shrines for the 5 KAAC Academic Subjects\r\n    this.shrines = [\r\n      { id: 'math', col: 3, row: 3, subject: SUBJECTS.MATH, label: 'Cipher Portal' },\r\n      { id: 'science', col: 16, row: 3, subject: SUBJECTS.SCIENCE, label: 'Verdant Portal' },\r\n      { id: 'social_studies', col: 3, row: 12, subject: SUBJECTS.SOCIAL_STUDIES, label: 'Time Portal' },\r\n      { id: 'language_arts', col: 16, row: 12, subject: SUBJECTS.LANGUAGE_ARTS, label: 'Archive Portal' },\r\n      { id: 'arts_humanities', col: 9, row: 2, subject: SUBJECTS.ARTS_HUMANITIES, label: 'Gallery Portal' },\r\n    ];\r\n\r\n    // Build starter map tile array (0=grass, 1=path, 2=water, 3=wall, 4=tree)\r\n    this.map = this.generateMap();\r\n\r\n    // Nearby interaction prompt\r\n    this.activeInteraction = null;\r\n\r\n    if (typeof document !== 'undefined') {\r\n      this.atlas = createTileAtlas();\r\n    }\r\n  }\r\n\r\n  generateMap() {\r\n    const tiles = [];\r\n    for (let r = 0; r < this.rows; r++) {\r\n      const row = [];\r\n      for (let c = 0; c < this.cols; c++) {\r\n        // Outer boundaries: trees\r\n        if (r === 0 || r === this.rows - 1 || c === 0 || c === this.cols - 1) {\r\n          row.push(4);\r\n        }\r\n        // Central crossroads path\r\n        else if (r === 8 || c === 9 || c === 10) {\r\n          row.push(1);\r\n        }\r\n        // Small decorative pond in lower corner\r\n        else if (r >= 11 && r <= 13 && c >= 9 && c <= 11) {\r\n          row.push(2);\r\n        }\r\n        // Grassy meadows\r\n        else {\r\n          row.push(0);\r\n        }\r\n      }\r\n      tiles.push(row);\r\n    }\r\n    return tiles;\r\n  }\r\n\r\n  /**\r\n   * Resizes canvas to match container while preserving crisp pixel ratio.\r\n   */\r\n  handleResize(containerWidth, containerHeight) {\r\n    if (!this.canvas) return;\r\n\r\n    // Calculate maximum integer or proportional scale that fits\r\n    const scaleX = containerWidth / this.width;\r\n    const scaleY = containerHeight / this.height;\r\n    const scale = Math.max(1, Math.min(scaleX, scaleY));\r\n\r\n    const displayWidth = Math.floor(this.width * scale);\r\n    const displayHeight = Math.floor(this.height * scale);\r\n\r\n    this.canvas.style.width = `${displayWidth}px`;\r\n    this.canvas.style.height = `${displayHeight}px`;\r\n\r\n    // Internal canvas resolution stays fixed at logical retro resolution\r\n    this.canvas.width = this.width;\r\n    this.canvas.height = this.height;\r\n\r\n    if (this.ctx) {\r\n      this.ctx.imageSmoothingEnabled = false;\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Updates game logic: input polling, player movement, collisions, and camera.\r\n   * @param {number} dt Delta time in seconds\r\n   * @param {import('./input.js').InputManager} input\r\n   * @param {boolean} reducedMotion\r\n   */\r\n  update(dt, input, reducedMotion = false) {\r\n    if (!input) return;\r\n\r\n    let dx = 0;\r\n    let dy = 0;\r\n\r\n    if (input.isDown('up')) {\r\n      dy -= 1;\r\n      this.player.direction = 'up';\r\n    }\r\n    if (input.isDown('down')) {\r\n      dy += 1;\r\n      this.player.direction = 'down';\r\n    }\r\n    if (input.isDown('left')) {\r\n      dx -= 1;\r\n      this.player.direction = 'left';\r\n    }\r\n    if (input.isDown('right')) {\r\n      dx += 1;\r\n      this.player.direction = 'right';\r\n    }\r\n\r\n    this.player.moving = dx !== 0 || dy !== 0;\r\n\r\n    if (this.player.moving) {\r\n      // Normalize diagonal vector\r\n      const length = Math.hypot(dx, dy);\r\n      const moveX = (dx / length) * this.player.speed * dt;\r\n      const moveY = (dy / length) * this.player.speed * dt;\r\n\r\n      // New candidate positions\r\n      const newX = this.player.x + moveX;\r\n      const newY = this.player.y + moveY;\r\n\r\n      // Bounds checking (prevent moving outside world boundaries)\r\n      const minX = this.tileSize;\r\n      const maxX = this.worldWidth - this.tileSize - this.player.width;\r\n      const minY = this.tileSize;\r\n      const maxY = this.worldHeight - this.tileSize - this.player.height;\r\n\r\n      this.player.x = Math.max(minX, Math.min(maxX, newX));\r\n      this.player.y = Math.max(minY, Math.min(maxY, newY));\r\n    }\r\n\r\n    // Camera centering with clamping\r\n    const targetCamX = this.player.x + this.player.width / 2 - this.width / 2;\r\n    const targetCamY = this.player.y + this.player.height / 2 - this.height / 2;\r\n    const maxCamX = Math.max(0, this.worldWidth - this.width);\r\n    const maxCamY = Math.max(0, this.worldHeight - this.height);\r\n\r\n    if (reducedMotion) {\r\n      this.camera.x = Math.max(0, Math.min(maxCamX, targetCamX));\r\n      this.camera.y = Math.max(0, Math.min(maxCamY, targetCamY));\r\n    } else {\r\n      this.camera.x += (Math.max(0, Math.min(maxCamX, targetCamX)) - this.camera.x) * 0.1;\r\n      this.camera.y += (Math.max(0, Math.min(maxCamY, targetCamY)) - this.camera.y) * 0.1;\r\n    }\r\n\r\n    // Check interaction proximity with Subject Shrines\r\n    this.activeInteraction = null;\r\n    const pCenterX = this.player.x + this.player.width / 2;\r\n    const pCenterY = this.player.y + this.player.height / 2;\r\n\r\n    for (const shrine of this.shrines) {\r\n      const sX = shrine.col * this.tileSize + this.tileSize / 2;\r\n      const sY = shrine.row * this.tileSize + this.tileSize / 2;\r\n      const dist = Math.hypot(pCenterX - sX, pCenterY - sY);\r\n\r\n      if (dist < 26) {\r\n        this.activeInteraction = shrine;\r\n        break;\r\n      }\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Main rendering routine.\r\n   * @param {number} time Current timestamp\r\n   */\r\n  render(time = 0) {\r\n    if (!this.ctx) return;\r\n    const ctx = this.ctx;\r\n\r\n    // Clear background\r\n    ctx.fillStyle = PALETTE.BG_DARK;\r\n    ctx.fillRect(0, 0, this.width, this.height);\r\n\r\n    ctx.save();\r\n    // Offset view by camera\r\n    ctx.translate(-Math.floor(this.camera.x), -Math.floor(this.camera.y));\r\n\r\n    // 1. Draw Tilemap\r\n    for (let r = 0; r < this.rows; r++) {\r\n      for (let c = 0; c < this.cols; c++) {\r\n        const tileType = this.map[r][c];\r\n        const destX = c * this.tileSize;\r\n        const destY = r * this.tileSize;\r\n\r\n        if (this.atlas) {\r\n          const srcX = tileType * this.tileSize;\r\n          ctx.drawImage(this.atlas, srcX, 0, 16, 16, destX, destY, 16, 16);\r\n        } else {\r\n          // Fallback solid tiles\r\n          const fallbackColors = [PALETTE.SCIENCE, PALETTE.SURFACE_ELEVATED, PALETTE.MATH, PALETTE.SURFACE, PALETTE.BG_DARK];\r\n          ctx.fillStyle = fallbackColors[tileType] || PALETTE.BG_DARK;\r\n          ctx.fillRect(destX, destY, 16, 16);\r\n        }\r\n      }\r\n    }\r\n\r\n    // 2. Draw 5 KAAC Subject Shrines / Portals\r\n    for (const shrine of this.shrines) {\r\n      const sx = shrine.col * this.tileSize;\r\n      const sy = shrine.row * this.tileSize;\r\n\r\n      // Base pedestal\r\n      ctx.fillStyle = PALETTE.SURFACE_ELEVATED;\r\n      ctx.fillRect(sx, sy + 6, 16, 10);\r\n      ctx.fillStyle = PALETTE.SURFACE_ACCENT;\r\n      ctx.fillRect(sx + 2, sy + 4, 12, 2);\r\n\r\n      // Glowing crystal / rune\r\n      ctx.fillStyle = shrine.subject.color;\r\n      ctx.fillRect(sx + 4, sy - 2, 8, 8);\r\n\r\n      // Energy pulse\r\n      const pulse = Math.sin(time / 250 + shrine.col) * 1.5;\r\n      ctx.fillStyle = PALETTE.TEXT_PRIMARY;\r\n      ctx.fillRect(sx + 6, sy + Math.floor(pulse), 4, 4);\r\n    }\r\n\r\n    // 3. Draw Player Character\r\n    const sprite = HERO_SPRITES[this.player.direction] || HERO_SPRITES.down;\r\n    renderPixelSprite(ctx, sprite, this.player.x, this.player.y, 2);\r\n\r\n    // 4. Draw Interaction Prompt if near a shrine\r\n    if (this.activeInteraction) {\r\n      const promptX = Math.floor(this.player.x - 24);\r\n      const promptY = Math.floor(this.player.y - 14);\r\n\r\n      ctx.fillStyle = PALETTE.SURFACE;\r\n      ctx.fillRect(promptX, promptY, 64, 12);\r\n      ctx.strokeStyle = this.activeInteraction.subject.color;\r\n      ctx.lineWidth = 1;\r\n      ctx.strokeRect(promptX, promptY, 64, 12);\r\n\r\n      ctx.fillStyle = PALETTE.TEXT_PRIMARY;\r\n      ctx.font = '8px system-ui, sans-serif';\r\n      ctx.textAlign = 'center';\r\n      ctx.fillText('[ACT] ' + this.activeInteraction.label.split(' ')[0], promptX + 32, promptY + 9);\r\n    }\r\n\r\n    ctx.restore();\r\n  }\r\n}\n\n/* --- SEMANTIC UI OVERLAY --- */\n\n// src/client/ui.js — Semantic Accessible UI Overlay\r\n// Follows WHATWG HTML Living Standard: explicit closing tags, type=\"button\", WCAG AA contrast.\r\n\r\n\r\nclass UIManager {\r\n  constructor(rootElement, playerProfile, callbacks = {}) {\r\n    this.root = rootElement;\r\n    this.player = playerProfile;\r\n    this.callbacks = callbacks; // onSettingsChange, onInteraction, etc.\r\n    this.activeTab = null; // 'map' | 'quests' | 'inventory' | 'settings' | null\r\n\r\n    this.render();\r\n    this.bindEvents();\r\n  }\r\n\r\n  render() {\r\n    if (!this.root) return;\r\n\r\n    this.root.innerHTML = `\r\n      <header class=\"game-hud\" role=\"banner\">\r\n        <div class=\"hud-player\">\r\n          <div class=\"avatar-badge\" aria-hidden=\"true\">\r\n            <span class=\"avatar-icon\">${getSvgIcon('sigil', PALETTE.BORDER_FOCUS, 22)}</span>\r\n          </div>\r\n          <div class=\"hud-meta\">\r\n            <div class=\"player-handle\" id=\"hud-handle\">${this.escapeHtml(this.player.handle)}</div>\r\n            <div class=\"player-stats\">\r\n              <span class=\"level-badge\">LV ${this.player.level}</span>\r\n              <div class=\"hp-bar-container\" title=\"Health: ${this.player.hp}/${this.player.maxHp}\">\r\n                <div class=\"hp-bar-fill\" style=\"width: ${(this.player.hp / this.player.maxHp) * 100}%\"></div>\r\n              </div>\r\n              <span class=\"gold-counter\">\r\n                <span class=\"gold-icon\" aria-hidden=\"true\">${getSvgIcon('scroll', PALETTE.GOLD, 14)}</span>\r\n                <span>${this.player.gold} G</span>\r\n              </span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <nav class=\"hud-nav\" aria-label=\"Game Navigation\">\r\n          <button type=\"button\" class=\"hud-btn\" data-tab=\"map\" title=\"Regional Map\">\r\n            ${getSvgIcon('map', PALETTE.TEXT_PRIMARY, 18)}\r\n            <span class=\"btn-label\">Map</span>\r\n          </button>\r\n          <button type=\"button\" class=\"hud-btn\" data-tab=\"quests\" title=\"Quest Log\">\r\n            ${getSvgIcon('quests', PALETTE.TEXT_PRIMARY, 18)}\r\n            <span class=\"btn-label\">Quests</span>\r\n          </button>\r\n          <button type=\"button\" class=\"hud-btn\" data-tab=\"inventory\" title=\"Inventory\">\r\n            ${getSvgIcon('inventory', PALETTE.TEXT_PRIMARY, 18)}\r\n            <span class=\"btn-label\">Items</span>\r\n          </button>\r\n          <button type=\"button\" class=\"hud-btn\" data-tab=\"settings\" title=\"Game Settings\">\r\n            ${getSvgIcon('settings', PALETTE.TEXT_PRIMARY, 18)}\r\n            <span class=\"btn-label\">Settings</span>\r\n          </button>\r\n        </nav>\r\n      </header>\r\n\r\n      <!-- Active Overlay Panels (Modals) -->\r\n      <div id=\"panel-container\" class=\"panel-container\" hidden>\r\n        <section id=\"panel-content\" class=\"panel-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"panel-title\">\r\n          <header class=\"panel-header\">\r\n            <h2 id=\"panel-title\" class=\"panel-title\">Menu</h2>\r\n            <button type=\"button\" class=\"panel-close-btn\" id=\"panel-close\" title=\"Close Panel\" aria-label=\"Close Panel\">\r\n              ${getSvgIcon('close', PALETTE.TEXT_PRIMARY, 18)}\r\n            </button>\r\n          </header>\r\n          <div id=\"panel-body\" class=\"panel-body\"></div>\r\n        </section>\r\n      </div>\r\n\r\n      <!-- Dialogue / Interaction Banner -->\r\n      <div id=\"interaction-banner\" class=\"interaction-banner\" role=\"status\" aria-live=\"polite\" hidden>\r\n        <div class=\"interaction-content\" id=\"interaction-text\"></div>\r\n      </div>\r\n\r\n      <!-- Mobile On-Screen Virtual Controller -->\r\n      <div class=\"touch-controls\" id=\"touch-controls\" aria-label=\"Virtual Touch Controller\">\r\n        <div class=\"virtual-dpad\" aria-label=\"Directional Pad\">\r\n          <button type=\"button\" class=\"dpad-btn dpad-up\" id=\"btn-up\" aria-label=\"Move Up\"></button>\r\n          <button type=\"button\" class=\"dpad-btn dpad-left\" id=\"btn-left\" aria-label=\"Move Left\"></button>\r\n          <button type=\"button\" class=\"dpad-btn dpad-center\" aria-hidden=\"true\" tabindex=\"-1\"></button>\r\n          <button type=\"button\" class=\"dpad-btn dpad-right\" id=\"btn-right\" aria-label=\"Move Right\"></button>\r\n          <button type=\"button\" class=\"dpad-btn dpad-down\" id=\"btn-down\" aria-label=\"Move Down\"></button>\r\n        </div>\r\n\r\n        <div class=\"virtual-actions\" aria-label=\"Action Buttons\">\r\n          <button type=\"button\" class=\"action-btn btn-act\" id=\"btn-act\" aria-label=\"Action\">ACT</button>\r\n          <button type=\"button\" class=\"action-btn btn-menu\" id=\"btn-menu\" aria-label=\"Menu\">MENU</button>\r\n        </div>\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  bindEvents() {\r\n    // HUD tab buttons\r\n    const navButtons = this.root.querySelectorAll('.hud-btn[data-tab]');\r\n    navButtons.forEach(btn => {\r\n      btn.addEventListener('click', () => {\r\n        soundEngine.playClick();\r\n        const tab = btn.getAttribute('data-tab');\r\n        this.openTab(tab);\r\n      });\r\n    });\r\n\r\n    // Close panel button\r\n    const closeBtn = this.root.querySelector('#panel-close');\r\n    if (closeBtn) {\r\n      closeBtn.addEventListener('click', () => {\r\n        soundEngine.playClick();\r\n        this.closePanel();\r\n      });\r\n    }\r\n\r\n    // Close on escape key\r\n    this.root.addEventListener('keydown', (e) => {\r\n      if (e.key === 'Escape' && this.activeTab) {\r\n        this.closePanel();\r\n      }\r\n    });\r\n\r\n    // Virtual MENU button toggles settings or closes\r\n    const virtualMenuBtn = this.root.querySelector('#btn-menu');\r\n    if (virtualMenuBtn) {\r\n      virtualMenuBtn.addEventListener('click', () => {\r\n        if (this.activeTab) {\r\n          this.closePanel();\r\n        } else {\r\n          this.openTab('settings');\r\n        }\r\n      });\r\n    }\r\n  }\r\n\r\n  getTouchElements() {\r\n    return {\r\n      up: this.root.querySelector('#btn-up'),\r\n      down: this.root.querySelector('#btn-down'),\r\n      left: this.root.querySelector('#btn-left'),\r\n      right: this.root.querySelector('#btn-right'),\r\n      action: this.root.querySelector('#btn-act'),\r\n      menu: this.root.querySelector('#btn-menu'),\r\n    };\r\n  }\r\n\r\n  openTab(tab) {\r\n    if (this.activeTab === tab) {\r\n      this.closePanel();\r\n      return;\r\n    }\r\n\r\n    this.activeTab = tab;\r\n    const container = this.root.querySelector('#panel-container');\r\n    const title = this.root.querySelector('#panel-title');\r\n    const body = this.root.querySelector('#panel-body');\r\n\r\n    if (!container || !title || !body) return;\r\n\r\n    soundEngine.playAlert();\r\n    container.removeAttribute('hidden');\r\n\r\n    switch (tab) {\r\n      case 'map':\r\n        title.textContent = \"Commonwealth Realms (Governor's Cup)\";\r\n        body.innerHTML = this.renderMapPanel();\r\n        break;\r\n      case 'quests':\r\n        title.textContent = 'Curriculum Quests';\r\n        body.innerHTML = this.renderQuestsPanel();\r\n        break;\r\n      case 'inventory':\r\n        title.textContent = 'Scholar Inventory & Relics';\r\n        body.innerHTML = this.renderInventoryPanel();\r\n        break;\r\n      case 'settings':\r\n        title.textContent = 'Game Settings & Accessibility';\r\n        body.innerHTML = this.renderSettingsPanel();\r\n        this.bindSettingsEvents(body);\r\n        break;\r\n      default:\r\n        this.closePanel();\r\n        return;\r\n    }\r\n  }\r\n\r\n  closePanel() {\r\n    this.activeTab = null;\r\n    const container = this.root.querySelector('#panel-container');\r\n    if (container) {\r\n      container.setAttribute('hidden', '');\r\n    }\r\n  }\r\n\r\n  renderMapPanel() {\r\n    const realms = Object.values(SUBJECTS);\r\n    return `\r\n      <div class=\"map-grid\">\r\n        ${realms.map(r => `\r\n          <article class=\"realm-card\" style=\"border-left: 4px solid ${r.color}\">\r\n            <h3 class=\"realm-title\" style=\"color: ${r.color}\">${this.escapeHtml(r.realm)}</h3>\r\n            <p class=\"realm-subject\">Subject: <strong>${this.escapeHtml(r.name)}</strong></p>\r\n            <p class=\"realm-boss\">Dungeon Boss: <em>${this.escapeHtml(r.boss)}</em></p>\r\n          </article>\r\n        `).join('')}\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  renderQuestsPanel() {\r\n    return `\r\n      <div class=\"quests-list\">\r\n        ${this.player.quests.map(q => `\r\n          <article class=\"quest-card\" style=\"border-left: 4px solid ${q.color}\">\r\n            <header class=\"quest-card-header\">\r\n              <h3 class=\"quest-title\">${this.escapeHtml(q.title)}</h3>\r\n              <span class=\"quest-badge status-${q.status}\">${this.escapeHtml(q.status.toUpperCase())}</span>\r\n            </header>\r\n            <p class=\"quest-desc\">${this.escapeHtml(q.description)}</p>\r\n            <footer class=\"quest-footer\">\r\n              <span class=\"quest-progress\">${this.escapeHtml(q.progress)}</span>\r\n              <span class=\"quest-rewards\">+${q.rewardXp} XP · +${q.rewardGold} Gold</span>\r\n            </footer>\r\n          </article>\r\n        `).join('')}\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  renderInventoryPanel() {\r\n    return `\r\n      <div class=\"inventory-grid\">\r\n        ${this.player.inventory.map(item => `\r\n          <article class=\"item-card\">\r\n            <div class=\"item-icon-box\" style=\"border: 1px solid ${item.color}\">\r\n              ${getSvgIcon(item.icon, item.color, 24)}\r\n            </div>\r\n            <div class=\"item-details\">\r\n              <h3 class=\"item-name\">${this.escapeHtml(item.name)}</h3>\r\n              <span class=\"item-type\">${this.escapeHtml(item.subject)} · ${this.escapeHtml(item.type)}</span>\r\n              <p class=\"item-desc\">${this.escapeHtml(item.description)}</p>\r\n            </div>\r\n          </article>\r\n        `).join('')}\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  renderSettingsPanel() {\r\n    const isMuted = soundEngine.isMuted();\r\n    const reducedMotion = Boolean(this.player.settings.reducedMotion);\r\n\r\n    return `\r\n      <div class=\"settings-form\">\r\n        <fieldset class=\"settings-group\">\r\n          <legend class=\"settings-legend\">Audio & Senses</legend>\r\n          <div class=\"setting-row\">\r\n            <label for=\"toggle-audio\" class=\"setting-label\">Sound Effects (Procedural FX)</label>\r\n            <button type=\"button\" id=\"toggle-audio\" class=\"btn-toggle ${isMuted ? 'muted' : 'active'}\">\r\n              ${isMuted ? getSvgIcon('audio-off', PALETTE.ERROR, 16) : getSvgIcon('audio-on', PALETTE.SUCCESS, 16)}\r\n              <span>${isMuted ? 'Muted' : 'Enabled'}</span>\r\n            </button>\r\n          </div>\r\n        </fieldset>\r\n\r\n        <fieldset class=\"settings-group\">\r\n          <legend class=\"settings-legend\">Motion & Accessibility</legend>\r\n          <div class=\"setting-row\">\r\n            <label for=\"toggle-motion\" class=\"setting-label\">Reduced Motion (No Screen Shake)</label>\r\n            <button type=\"button\" id=\"toggle-motion\" class=\"btn-toggle ${reducedMotion ? 'active' : ''}\">\r\n              <span>${reducedMotion ? 'Enabled (Calm)' : 'Standard'}</span>\r\n            </button>\r\n          </div>\r\n        </fieldset>\r\n\r\n        <fieldset class=\"settings-group\">\r\n          <legend class=\"settings-legend\">Child Privacy & Identity</legend>\r\n          <div class=\"setting-row\">\r\n            <div class=\"setting-label\">\r\n              <span>Adventurer Handle</span>\r\n              <small class=\"setting-subtext\">Zero PII. Randomly generated.</small>\r\n            </div>\r\n            <button type=\"button\" id=\"btn-reroll-name\" class=\"btn-secondary\">\r\n              Reroll Name\r\n            </button>\r\n          </div>\r\n        </fieldset>\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  bindSettingsEvents(container) {\r\n    const audioBtn = container.querySelector('#toggle-audio');\r\n    if (audioBtn) {\r\n      audioBtn.addEventListener('click', () => {\r\n        const isMuted = soundEngine.toggleMute();\r\n        this.player.settings.audioMuted = isMuted;\r\n        soundEngine.playClick();\r\n        this.openTab('settings');\r\n        if (this.callbacks.onSettingsChange) {\r\n          this.callbacks.onSettingsChange(this.player.settings);\r\n        }\r\n      });\r\n    }\r\n\r\n    const motionBtn = container.querySelector('#toggle-motion');\r\n    if (motionBtn) {\r\n      motionBtn.addEventListener('click', () => {\r\n        this.player.settings.reducedMotion = !this.player.settings.reducedMotion;\r\n        soundEngine.playClick();\r\n        this.openTab('settings');\r\n        if (this.callbacks.onSettingsChange) {\r\n          this.callbacks.onSettingsChange(this.player.settings);\r\n        }\r\n      });\r\n    }\r\n\r\n    const rerollBtn = container.querySelector('#btn-reroll-name');\r\n    if (rerollBtn) {\r\n      rerollBtn.addEventListener('click', () => {\r\n        soundEngine.playChime();\r\n        if (this.callbacks.onRerollHandle) {\r\n          const newHandle = this.callbacks.onRerollHandle();\r\n          this.player.handle = newHandle;\r\n          const hudHandle = this.root.querySelector('#hud-handle');\r\n          if (hudHandle) hudHandle.textContent = newHandle;\r\n          this.openTab('settings');\r\n        }\r\n      });\r\n    }\r\n  }\r\n\r\n  showInteractionBanner(text) {\r\n    const banner = this.root.querySelector('#interaction-banner');\r\n    const content = this.root.querySelector('#interaction-text');\r\n    if (!banner || !content) return;\r\n\r\n    content.textContent = text;\r\n    banner.removeAttribute('hidden');\r\n  }\r\n\r\n  hideInteractionBanner() {\r\n    const banner = this.root.querySelector('#interaction-banner');\r\n    if (banner) {\r\n      banner.setAttribute('hidden', '');\r\n    }\r\n  }\r\n\r\n  escapeHtml(str) {\r\n    if (typeof str !== 'string') return '';\r\n    return str\r\n      .replace(/&/g, '&amp;')\r\n      .replace(/</g, '&lt;')\r\n      .replace(/>/g, '&gt;')\r\n      .replace(/\"/g, '&quot;')\r\n      .replace(/'/g, '&#39;');\r\n  }\r\n}\n\n/* --- APPLICATION ORCHESTRATOR --- */\n\n// src/client/app.js — Core Game Client Orchestrator\r\n// Connects Input, Game World, Canvas 2D Engine, Audio, and UI Overlay.\r\n\r\n\r\nconst STORAGE_KEY = 'quest_ky_guest_profile';\r\n\r\nclass GameApp {\r\n  constructor(canvasElement, uiRootElement) {\r\n    this.canvas = canvasElement;\r\n    this.uiRoot = uiRootElement;\r\n\r\n    // Load local guest profile or create new\r\n    this.player = this.loadProfile();\r\n\r\n    // Initialize subsystems\r\n    this.input = new InputManager();\r\n    this.renderer = new GameRenderer(this.canvas);\r\n    this.ui = new UIManager(this.uiRoot, this.player, {\r\n      onSettingsChange: (settings) => this.saveProfile(),\r\n      onRerollHandle: () => {\r\n        const handle = generateAdventurerHandle();\r\n        this.player.handle = handle;\r\n        this.saveProfile();\r\n        return handle;\r\n      },\r\n    });\r\n\r\n    // Bind touch controls\r\n    const touchElements = this.ui.getTouchElements();\r\n    this.input.bindVirtualControls(touchElements);\r\n    this.input.initKeyboard();\r\n\r\n    // Apply audio preference\r\n    if (this.player.settings.audioMuted) {\r\n      soundEngine.toggleMute(true);\r\n    }\r\n\r\n    // Animation loop state\r\n    this.lastTime = 0;\r\n    this.animationFrameId = null;\r\n    this.running = false;\r\n\r\n    // Bind loop\r\n    this.tick = this.tick.bind(this);\r\n    this.onResize = this.onResize.bind(this);\r\n  }\r\n\r\n  loadProfile() {\r\n    try {\r\n      if (typeof localStorage !== 'undefined') {\r\n        const saved = localStorage.getItem(STORAGE_KEY);\r\n        if (saved) {\r\n          return JSON.parse(saved);\r\n        }\r\n      }\r\n    } catch {\r\n      // LocalStorage access restricted / private browsing fallback\r\n    }\r\n    return createDefaultPlayerProfile();\r\n  }\r\n\r\n  saveProfile() {\r\n    try {\r\n      if (typeof localStorage !== 'undefined') {\r\n        localStorage.setItem(STORAGE_KEY, JSON.stringify(this.player));\r\n      }\r\n    } catch {\r\n      // Ignore storage write error\r\n    }\r\n  }\r\n\r\n  start() {\r\n    if (this.running) return;\r\n    this.running = true;\r\n\r\n    // Setup resize listener\r\n    if (typeof window !== 'undefined') {\r\n      window.addEventListener('resize', this.onResize);\r\n      this.onResize();\r\n    }\r\n\r\n    this.lastTime = performance.now();\r\n    this.animationFrameId = requestAnimationFrame(this.tick);\r\n  }\r\n\r\n  stop() {\r\n    this.running = false;\r\n    if (this.animationFrameId) {\r\n      cancelAnimationFrame(this.animationFrameId);\r\n    }\r\n    if (typeof window !== 'undefined') {\r\n      window.removeEventListener('resize', this.onResize);\r\n    }\r\n    this.input.destroy();\r\n  }\r\n\r\n  onResize() {\r\n    if (!this.canvas || typeof window === 'undefined') return;\r\n    // Calculate available dimensions for canvas\r\n    const container = this.canvas.parentElement || document.body;\r\n    const width = container.clientWidth || window.innerWidth;\r\n    const height = (container.clientHeight || window.innerHeight) * 0.65;\r\n    this.renderer.handleResize(width, height);\r\n  }\r\n\r\n  tick(currentTime) {\r\n    if (!this.running) return;\r\n\r\n    const dt = Math.min((currentTime - this.lastTime) / 1000, 0.1); // Clamp to 100ms max\r\n    this.lastTime = currentTime;\r\n\r\n    // Handle [ACT] interact button trigger\r\n    if (this.input.isJustPressed('action')) {\r\n      if (this.renderer.activeInteraction) {\r\n        soundEngine.playChime();\r\n        this.ui.showInteractionBanner(\r\n          `Examining ${this.renderer.activeInteraction.label}: Gateway to ${this.renderer.activeInteraction.subject.realm}.`\r\n        );\r\n      }\r\n    }\r\n\r\n    // Handle [MENU] button trigger\r\n    if (this.input.isJustPressed('menu')) {\r\n      if (this.ui.activeTab) {\r\n        this.ui.closePanel();\r\n      } else {\r\n        this.ui.openTab('settings');\r\n      }\r\n    }\r\n\r\n    // Update game physics and camera\r\n    this.renderer.update(dt, this.input, Boolean(this.player.settings.reducedMotion));\r\n\r\n    // Clear just-pressed buffer\r\n    this.input.update();\r\n\r\n    // Render frame\r\n    this.renderer.render(currentTime);\r\n\r\n    this.animationFrameId = requestAnimationFrame(this.tick);\r\n  }\r\n}";

export function createHtmlShell() {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">
  <meta name="theme-color" content="${PALETTE.BG_DARK}">
  <meta name="description" content="QUEST: Kentucky — Governor's Cup Middle Grades RPG">
  <link rel="manifest" href="/manifest.webmanifest">
  <title>QUEST: Kentucky — Governor's Cup RPG</title>
  <style>
${GAME_CSS}
  </style>
</head>
<body>
  <main id="app-root">
    <div id="ui-root"></div>
    <div role="region" aria-label="Kentucky World Viewport" class="canvas-container">
      <canvas id="game-canvas" width="${VIEWPORT.LOGICAL_WIDTH}" height="${VIEWPORT.LOGICAL_HEIGHT}"></canvas>
    </div>
  </main>

  <script type="module">
${CLIENT_BUNDLE}

    if ('serviceWorker' in navigator) {
      window.addEventListener('load', () => {
        navigator.serviceWorker.register('/sw.js').catch(() => {});
      });
    }

    window.addEventListener('DOMContentLoaded', () => {
      const canvas = document.getElementById('game-canvas');
      const uiRoot = document.getElementById('ui-root');
      if (canvas && uiRoot && typeof GameApp !== 'undefined') {
        const app = new GameApp(canvas, uiRoot);
        app.start();
        window.__QUEST_APP__ = app;
      }
    });
  </script>
</body>
</html>`;
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    const securityHeaders = {
      'X-Content-Type-Options': 'nosniff',
      'X-Frame-Options': 'DENY',
      'Referrer-Policy': 'strict-origin-when-cross-origin',
    };

    if (url.pathname === '/api/health') {
      return new Response(JSON.stringify({
        status: 'ok',
        game: 'QUEST: Kentucky',
        gradeBand: '6-8',
        phase: 1,
        mode: 'guest-first',
      }), {
        headers: {
          'Content-Type': 'application/json',
          ...securityHeaders,
        },
      });
    }

    if (url.pathname === '/api/regions') {
      return new Response(JSON.stringify({
        regions: Object.values(SUBJECTS),
      }), {
        headers: {
          'Content-Type': 'application/json',
          'Cache-Control': 'public, max-age=3600',
          ...securityHeaders,
        },
      });
    }

    if (url.pathname === '/api/session') {
      const guestId = (crypto && crypto.randomUUID) ? crypto.randomUUID() : 'guest_' + Math.random().toString(36).substring(2, 10);
      return new Response(JSON.stringify({
        guestId,
        gradeBand: '6-8',
        authenticated: false,
      }), {
        headers: {
          'Content-Type': 'application/json',
          ...securityHeaders,
        },
      });
    }

    if (url.pathname === '/manifest.webmanifest' || url.pathname === '/manifest.json') {
      return new Response(JSON.stringify(createManifest()), {
        headers: {
          'Content-Type': 'application/manifest+json; charset=utf-8',
          'Cache-Control': 'public, max-age=86400',
          ...securityHeaders,
        },
      });
    }

    if (url.pathname === '/sw.js') {
      return new Response(createServiceWorker(), {
        headers: {
          'Content-Type': 'application/javascript; charset=utf-8',
          'Cache-Control': 'no-cache',
          ...securityHeaders,
        },
      });
    }

    const html = createHtmlShell();
    return new Response(html, {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'public, max-age=3600',
        ...securityHeaders,
      },
    });
  },
};
